package com.malafel.hiscore.notifications;

import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.WidgetNode;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
public class NotificationManager
{
	private static final int SCRIPT_ID = 3343; // NOTIFICATION_DISPLAY_INIT

	private static final int COMPONENT_ID = WidgetUtil.packComponentId(303, 2); // (interfaceId << 16) | childId

	private static final int INTERFACE_ID = 660;

	private final Queue<Notification> notifications = new ConcurrentLinkedQueue<>();

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Subscribe
	public void onGameTick(GameTick event)
	{
		processNotification();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		// Clear notifications when not logged in
		switch (gameStateChanged.getGameState())
		{
			case HOPPING:
			case LOGGING_IN:
			case LOGIN_SCREEN:
			case LOGIN_SCREEN_AUTHENTICATOR:
			case CONNECTION_LOST:
				clearNotifications();
				break;
		}
	}

	public void startUp()
	{
		log.debug("NotificationManager startUp()");
		eventBus.register(this);
	}

	public void shutDown()
	{
		log.debug("NotificationManager shutDown()");
		clearNotifications();
		eventBus.unregister(this);
	}

	public void addNotification(String title, String text)
	{
		addNotification(title, text, -1);
	}

	public void addNotification(String title, String text, int color)
	{
		Notification notification = new Notification(title, text, color);
		notifications.offer(notification);
	}

	/**
	 * Processes a notification
	 */
	private void processNotification()
	{
		// Don't process when any type of notification is visible (collection log, league task, one of our own, ...)
		if (client.getWidget(INTERFACE_ID, 1) != null)
		{
			return;
		}
		// Only process notifications if the queue is not empty AND the queue is not processing any notifications.
		if (!notifications.isEmpty())
		{
			// Get and remove the first element in the notifications queue.
			Notification notification = notifications.poll();

			// Display notification
			displayNotification(notification);
		}
	}


	/**
	 * Clears the current list of notifications and makes sure the processing notifications state is set to false
	 */
	public void clearNotifications()
	{
		notifications.clear();
	}

	/**
	 * Display a notification and close it afterward.
	 *
	 * @param notification Notification
	 */
	private void displayNotification(Notification notification) throws IllegalStateException, IllegalArgumentException
	{
		WidgetNode notificationNode = client.openInterface(COMPONENT_ID, INTERFACE_ID, WidgetModalMode.MODAL_CLICKTHROUGH);
		Widget notificationWidget = client.getWidget(INTERFACE_ID, 1);

		// Runs a client script to set the initial title, text and color values of the notifications
		client.runScript(SCRIPT_ID, notification.getTitle(), notification.getText(), notification.getColor());

		// Only remove notification when widget is fully closed.
		clientThread.invokeLater(() -> {
			assert notificationWidget != null;

			if (notificationWidget.getWidth() > 0)
			{
				return false;
			}

			// Close the interface
			client.closeInterface(notificationNode, true);

			// Invoke done
			return true;
		});
	}
}

package com.malafel.hiscore.util;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.GameTick;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicInteger;

@Slf4j
@Singleton
public class RateLimitedHttpClientInterface {
    private static final int MAX_ACTIVE_CALLS = 4;
    private static final Duration MIN_TIME_BETWEEN_CALLS = Duration.ofMillis(5000);

    private class CallWrapper {
        public CompletableFuture<Response> future;
        public Request request;
    }

    private final OkHttpClient client;
    private Queue<CallWrapper> callQueue = new LinkedList<CallWrapper>();
    private Instant timeOfLastRequest;
    private AtomicInteger numActiveCalls = new AtomicInteger(0);

    @Inject
    public RateLimitedHttpClientInterface(OkHttpClient client) {
        this.client = client;
        this.timeOfLastRequest = Instant.now();
    }

    public void cancelAll() {
        // This empties the queue and sets all futures as canceled. The setting to canceled is probably not needed, but
        // it does provide context to any consumers of the Future.
        while (!callQueue.isEmpty()) {
            CallWrapper call = callQueue.poll();
            call.future.cancel(true);
        }
    }

    public CompletableFuture<Response> call(Request request) {
        CallWrapper w = new CallWrapper();
        w.request = request;
        w.future = new CompletableFuture<Response>();
        callQueue.add(w);
        return w.future;
    }

    public void process(GameTick event) {
        while (numActiveCalls.get() < MAX_ACTIVE_CALLS && !callQueue.isEmpty()) {
            if (timeOfLastRequest.plus(MIN_TIME_BETWEEN_CALLS).isAfter(Instant.now())) {
                break;
            }

            CallWrapper front = callQueue.poll();
            assert front != null;
            if (front.future.isCancelled()) {
                continue;
            }
            numActiveCalls.incrementAndGet();
            timeOfLastRequest = Instant.now();
            client.newCall(front.request).enqueue(new Callback() {
                @Override
                public void onFailure(Call call, IOException e) {
                    numActiveCalls.decrementAndGet();
                    front.future.completeExceptionally(e);
                }
                @Override
                public void onResponse(Call call, Response response) {
                    numActiveCalls.decrementAndGet();
                    try (response) {
                        front.future.complete(response);
                    } catch (Exception e) {
                        front.future.completeExceptionally(e);
                    }
                }
            });
            break;
        }
    }

}

package com.malafel.hiscore.util;

import java.awt.Color;

import com.malafel.hiscore.HiscoreNotificationsConfig;
import com.malafel.hiscore.leaderboard.BossInfo;
import com.malafel.hiscore.leaderboard.BossLeaderboardEntry;
import com.malafel.hiscore.leaderboard.SkillLeaderboardEntry;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;

import static java.lang.Math.min;

@Slf4j
public class Util
{
	private static final int IN_LMS_VARBIT = 5314;

	/**
	 * Checks if a level is a valid real level (>= 1 and <= 99)
	 *
	 * @param level int
	 * @return boolean
	 */
	public static boolean isValidRealLevel(int level)
	{
		return level >= 1 && level <= Experience.MAX_REAL_LEVEL;
	}


	/**
	 * Checks if a number is a valid XP target (>= 1 and <= 200M)
	 *
	 * @param xp int
	 * @return boolean
	 */
	public static boolean isValidExperience(int xp)
	{
		return xp > 0 && xp <= Experience.MAX_SKILL_XP;
	}


	/**
	 * @param string String
	 * @return boolean
	 */
	public static boolean isInteger(String string)
	{
		try
		{
			Integer.parseInt(string);
			return true;
		}
		catch (NumberFormatException e)
		{
			return false;
		}
	}

	/**
	 * Gets the int value for a color.
	 *
	 * @param color color
	 * @return int
	 */
	public static int getIntValue(Color color)
	{
		int red = color.getRed();
		int green = color.getGreen();
		int blue = color.getBlue();

		// Combine RGB values into a single integer
		return (red << 16) | (green << 8) | blue;
	}


	/**
	 * Replaces the words $skill and $level from the text to the passed skill and level respectively
	 *
	 * @param text  String
	 * @param skill Skill
	 * @param level int
	 * @return String
	 */
	public static String replaceSkillAndLevel(String text, Skill skill, int level)
	{
		return Text.escapeJagex(text
			.replaceAll("\\$skill", skill.getName())
			.replaceAll("\\$level", Integer.toString(level)));
	}

	/**
	 * Replaces the words $skill and $xp from the text to the passed skill and level respectively
	 *
	 * @param text  String
	 * @param skill Skill
	 * @param xp    int
	 * @return String
	 */
	public static String replaceSkillAndExperience(String text, Skill skill, int xp)
	{
		return Text.escapeJagex(text
			.replaceAll("\\$skill", skill.getName())
			.replaceAll("\\$xp", QuantityFormatter.formatNumber(xp)));
	}


	/** Replaces the words $skill, $xp, $rank, and $player from the text to the passed skill and data from
	 * leaderboardEntry
	 *
	 * @param text  String
	 * @param skill Skill
	 * @param leaderboardEntry LeaderboardEntry
	 * @return String
	 */
	public static String replaceSkillLeaderboardValues(String text, Skill skill, SkillLeaderboardEntry leaderboardEntry)
	{
		return Text.escapeJagex(text
				.replaceAll("\\$skill", skill.getName())
				.replaceAll("\\$xp", QuantityFormatter.formatNumber(leaderboardEntry.xp))
				.replaceAll("\\$rank", QuantityFormatter.formatNumber(leaderboardEntry.rank))
				.replaceAll("\\$player", leaderboardEntry.name)
				.replaceAll("\\$name", leaderboardEntry.name));
	}

	/** Replaces the words $skill, $xp, $rank, and $player from the text to the passed skill and data from
	 * leaderboardEntry
	 *
	 * @param text  String
	 * @param boss BossInfo
	 * @param leaderboardEntry LeaderboardEntry
	 * @return String
	 */
	public static String replaceBossLeaderboardValues(String text, BossInfo boss, BossLeaderboardEntry leaderboardEntry)
	{
		return Text.escapeJagex(text
				.replaceAll("\\$boss", boss.chatCommandsLongName)
				.replaceAll("\\$passedkc", QuantityFormatter.formatNumber(leaderboardEntry.score))
				.replaceAll("\\$passedscore", QuantityFormatter.formatNumber(leaderboardEntry.score))
				.replaceAll("\\$kc", QuantityFormatter.formatNumber(leaderboardEntry.score+1))
				.replaceAll("\\$score", QuantityFormatter.formatNumber(leaderboardEntry.score+1))
				.replaceAll("\\$rank", QuantityFormatter.formatNumber(leaderboardEntry.rank))
				.replaceAll("\\$player", leaderboardEntry.name)
				.replaceAll("\\$name", leaderboardEntry.name));
	}

